import math

def build_agent(sandbox):
    return None

def agent_action(sandbox, agent_body, step_count):
    pos_x, pos_y = sandbox.get_lander_position()
    angle = sandbox.get_lander_angle()
    half_width, half_height = sandbox.get_lander_size()
    fuel = sandbox.get_remaining_fuel()
    ground_y = sandbox.get_ground_y_top()
    body = sandbox.get_lander_body()
    vx = body.linearVelocity.x
    vy = body.linearVelocity.y
    delay_steps = sandbox.get_thrust_delay_steps()

    # Check no-fly zone
    in_nofly = False
    for x, y in [
        (pos_x - half_width, pos_y + half_height),
        (pos_x + half_width, pos_y + half_height),
        (pos_x - half_width, pos_y - half_height),
        (pos_x + half_width, pos_y - half_height)
    ]:
        if 10.5 <= x <= 13.5:
            if y < 6.0 or y > 15.5:
                in_nofly = True
                break

    # Initialize thrust and torque
    f1 = 0.0  # Main engine thrust
    f2 = 0.0  # Steering torque

    if in_nofly:
        # Adjust vertical position to stay within no-fly zone
        if pos_y < 6.0:
            f1 = 1000.0  # Upward thrust
        elif pos_y > 15.5:
            f1 = -1000.0  # Downward thrust
        else:
            f1 = 0.0
            f2 = 0.0
    else:
        # Predict platform position and velocity
        t = step_count / 60.0
        platform_x = 17.0 + 1.8 * math.sin(2 * math.pi * t / 6.0)
        platform_vel_x = 1.8 * (2 * math.pi / 6.0) * math.cos(2 * math.pi * t / 6.0)
        dx = platform_x - pos_x

        # Check if near platform
        if abs(dx) < 5.0:  # Adjust threshold as needed
            # Start landing approach
            # Adjust horizontal velocity to match platform's velocity
            error_vx = vx - platform_vel_x
            if error_vx > 0.5:
                # Too fast, reduce thrust
                f1 = -200.0
                f2 = -5.0  # Tilt back to direct thrust left
            elif error_vx < -0.5:
                # Too slow, increase thrust
                f1 = 200.0
                f2 = 5.0  # Tilt forward to direct thrust right
            else:
                # Match velocity
                f1 = 0.0
                f2 = 0.0

            # Adjust vertical velocity to land softly
            if pos_y > ground_y + 0.02:
                if abs(vy) > 2.6:
                    f1 = 1000.0  # Upward thrust to reduce vertical speed
                else:
                    f1 = 500.0
            else:
                if abs(vy) > 2.6:
                    f1 = 1000.0
                else:
                    f1 = 0.0

            # Check angle
            if abs(angle) > 0.122:  # 7 degrees in radians
                if angle > 0:
                    f2 = -10.0
                else:
                    f2 = 10.0
            else:
                f2 = 0.0
        else:
            # Move towards platform
            if pos_x < platform_x:
                # Move right
                f1 = 500.0
                f2 = 10.0  # Tilt forward
            else:
                # Move left
                f1 = -500.0
                f2 = -10.0  # Tilt back

            # Adjust vertical velocity
            if pos_y > ground_y + 0.02:
                if abs(vy) > 2.6:
                    f1 = 1000.0
                else:
                    f1 = 500.0
            else:
                if abs(vy) > 2.6:
                    f1 = 1000.0
                else:
                    f1 = 0.0

            # Check angle
            if abs(angle) > 0.122:
                if angle > 0:
                    f2 = -10.0
                else:
                    f2 = 10.0
            else:
                f2 = 0.0

        # Fuel efficiency
        if fuel < 500.0:
            f1 = max(f1, 0.0)
            f2 = max(f2, 0.0)
            f1 = max(f1 - 200.0, 0.0)
            f2 = max(f2 - 5.0, 0.0)

    # Clamp thrust and torque
    f1 = max(min(f1, 1200.0), 0.0)
    f2 = max(min(f2, 120.0), 0.0)

    # Apply thrust and torque
    sandbox.apply_thrust(f1, f2)
